1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items?: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: Step[];
20	};
21	
22	export type QuoteResult = {
23	  premium: number;
24	};
25	
26	// A scenario's results are heterogeneous: a quote step yields a premium, and a
27	// claim step will yield a payout. The union has one member today.
28	export type StepResult = QuoteResult;
29	
30	export type ScenarioResults = {
31	  results: StepResult[];
32	};
33	
34	const PROCESSING_FEE = 5;
35	
36	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
37	  sword: 100,
38	  amulet: 60,
39	  staff: 80,
40	  potion: 40,
41	  rune: 25,
42	  moonstone: 25,
43	};
44	
45	// Charged on every quote, unconditionally — it is the cost of assessing the
46	// items, not a penalty for being a new customer. Named "first insurance" in
47	// some of the domain material, which misleads: it does not depend on customer
48	// history or on the quote's position in the scenario.
49	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
50	
51	const percentOf = (amount: number, percent: number): number =>
52	  (amount * percent) / 100;
53	
54	const itemBasePremium = (item: Item): number =>
55	  BASE_PREMIUM_BY_TYPE[item.type];
56	
57	const BLOCK_SIZE = 3;
58	
59	const BLOCK_PREMIUM = 60;
60	
61	const sumOf = (amounts: number[]): number =>
62	  amounts.reduce((sum, amount) => sum + amount, 0);
63	
64	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
65	
66	const sumOfItemBasePremiums = (items: Item[]): number =>
67	  sumOf(items.map(itemBasePremium));
68	
69	const groupByType = (items: Item[]): Item[][] => {
70	  const types = new Set(items.map((item) => item.type));
71	
72	  return [...types].map((type) => items.filter((item) => item.type === type));
73	};
74	
75	const alikeGroupBasePremium = (items: Item[]): number =>
76	  formsABlock(items) ? BLOCK_PREMIUM : sumOfItemBasePremiums(items);
77	
78	const policyBasePremium = (items: Item[]): number =>
79	  sumOf(groupByType(items).map(alikeGroupBasePremium));
80	
81	const roundPremiumInMHPCOsFavor = (amount: number): number =>
82	  Math.ceil(amount);
83	
84	// The inputs a single quote is computed from: `items` drives the base premium
85	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
86	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
87	// general — a claim step is not a contract and must not trigger the follow-up
88	// discount.
89	type QuoteRequest = {
90	  customer: Customer;
91	  items: Item[];
92	  precedingQuoteCount: number;
93	};
94	
95	const LOYALTY_YEARS = 2;
96	
97	const LOYALTY_DISCOUNT_PERCENT = 20;
98	
99	// Modifier percents are signed so surcharges and discounts can be summed
100	// uniformly; a discount enters the sum as its negation.
101	const asDiscount = (percent: number): number => -percent;
102	
103	const isLoyal = (customer: Customer): boolean =>
104	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
105	
106	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
107	
108	const isFollowUpContract = (request: QuoteRequest): boolean =>
109	  request.precedingQuoteCount > 0;
110	
111	const policyModifierPercents = (request: QuoteRequest): number[] => [
112	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
113	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
114	  ...(isFollowUpContract(request)
115	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
116	    : []),
117	];
118	
119	// Policy-wide modifiers do NOT compound: each is an independent percentage of
120	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
121	// would give a different, wrong answer.
122	const applyPolicyModifiers = (
123	  basePremium: number,
124	  request: QuoteRequest,
125	): number =>
126	  basePremium +
127	  sumOf(
128	    policyModifierPercents(request).map((percent) =>
129	      percentOf(basePremium, percent),
130	    ),
131	  );
132	
133	const CURSE_SURCHARGE_PERCENT = 50;
134	
135	const HIGH_ENCHANTMENT_LEVEL = 5;
136	
137	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
138	
139	const isHighlyEnchanted = (item: Item): boolean =>
140	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
141	
142	const isCursed = (item: Item): boolean => item.cursed === true;
143	
144	type ItemSurchargeRule = {
145	  applies: (item: Item) => boolean;
146	  percent: number;
147	};
148	
149	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
150	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
151	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
152	];
153	
154	// Item-scoped surcharges are charged on the item's own base premium, so they
155	// must NOT go through applyPolicyModifiers.
156	const itemSurcharges = (item: Item): number =>
157	  sumOf(
158	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
159	      percentOf(itemBasePremium(item), rule.percent),
160	    ),
161	  );
162	
163	const policyItemSurcharges = (items: Item[]): number =>
164	  sumOf(items.map(itemSurcharges));
165	
166	const quotePremium = (request: QuoteRequest): number =>
167	  roundPremiumInMHPCOsFavor(
168	    applyPolicyModifiers(policyBasePremium(request.items), request) +
169	      policyItemSurcharges(request.items) +
170	      PROCESSING_FEE,
171	  );
172	
173	const isQuote = (step: Step): boolean => step.op === "quote";
174	
175	// What the scenario has accumulated so far. Steps are folded rather than mapped
176	// because a step's result depends on the steps before it: `precedingQuoteCount`
177	// drives the follow-up discount today, and claim steps will thread a remaining
178	// cap through the same carry.
179	type ScenarioState = {
180	  results: StepResult[];
181	  precedingQuoteCount: number;
182	};
183	
184	const INITIAL_STATE: ScenarioState = { results: [], precedingQuoteCount: 0 };
185	
186	// Running a step is a state transition: it reads the carry accumulated by the
187	// preceding steps and returns the next carry. Every step kind gets its own
188	// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
189	// will be added without touching the quote path.
190	type StepRunner = (
191	  customer: Customer,
192	  state: ScenarioState,
193	  step: Step,
194	) => ScenarioState;
195	
196	const appendResult = (
197	  state: ScenarioState,
198	  result: StepResult,
199	): ScenarioState => ({ ...state, results: [...state.results, result] });
200	
201	const runQuoteStep: StepRunner = (customer, state, step) => {
202	  const premium = quotePremium({
203	    customer,
204	    items: step.items ?? [],
205	    precedingQuoteCount: state.precedingQuoteCount,
206	  });
207	
208	  return {
209	    ...appendResult(state, { premium }),
210	    precedingQuoteCount: state.precedingQuoteCount + 1,
211	  };
212	};
213	
214	const runStep: StepRunner = (customer, state, step) =>
215	  isQuote(step) ? runQuoteStep(customer, state, step) : state;
216	
217	// The customer is scenario-wide, so it is closed over rather than threaded
218	// through the fold alongside the per-step state.
219	const stepRunnerFor =
220	  (customer: Customer) => (state: ScenarioState, step: Step) =>
221	    runStep(customer, state, step);
222	
223	export const runScenario = (scenario: Scenario): ScenarioResults => ({
224	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
225	    .results,
226	});
